"""Render the case-led reading structure from an editorial map, preserving source articles."""
from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1];M=json.loads((R/'assets/case-studies.json').read_text());D=json.loads((R/'assets/research-data.json').read_text());E=html.escape
GROUPS={g['id']:g for g in M['groups']};SOURCES={s['id']:s for s in D['sources']}
def card(c,base=''):
 return f'<a class="case-card" data-case="{E((c["place"]+" "+c["title"]+" "+c["question"]).lower(),quote=True)}" data-topic="{c["group"]}" href="{base}case-studies/{c["id"]}/"><span class="eyebrow">{E(c["place"])} / DOCUMENT-BASED CASE STUDY</span><h3>{E(c["title"])}</h3><p>{E(c["question"])}</p><span class="case-card-foot">Follow the case <span>→</span></span></a>'
def collection(base='',filters=False):
 tools='<div class="filterbar"><label>Find a case<input id="case-filter" type="search" placeholder="Try Delhi, an objection or a deadline…"></label><label>Explore a question<select id="case-topic"><option value="all">All four groups</option>'+''.join(f'<option value="{g["id"]}">{E(g["title"])}</option>' for g in M['groups'])+'</select></label><span id="case-count" aria-live="polite">8 case studies</span></div>' if filters else ''
 return tools+''.join(f'<section class="case-group" id="{g["id"]}" data-case-group><div class="case-group-head"><span class="group-number">0{n}</span><div><h2>{E(g["title"])}</h2><p>{E(g["intro"])}</p></div></div><div class="case-grid">'+''.join(card(c,base) for c in M['cases'] if c['group']==g['id'])+'</div></section>' for n,g in enumerate(M['groups'],1))+'<p class="empty-state hidden" id="case-empty">No matching case. Try a place name or choose all four groups.</p>'
def write(path,title,deck,body,base):
 p=R/path/'index.html';p.parent.mkdir(exist_ok=True,parents=True)
 if p.exists():t=p.read_text()
 else:
  t=(R/'research/index.html').read_text()
  if base!='../':
   t=re.sub(r'(href|src)="\.\./',lambda m:m[1]+'="'+base,t)
   t=t.replace('data-base="../"','data-base="'+base+'"')
 t=re.sub(r'<main .*?</main>',lambda _:f'<main id="main" class="container">{body}</main>',t,flags=re.S)
 t=re.sub(r'<title>.*?</title>','<title>'+E(title)+' | The SIR Files</title>',t)
 t=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="'+E(deck,quote=True)+'">',t)
 p.write_text(t)
write('case-studies','The case studies','Eight document-based case studies grouped by the questions they help answer.', '<div class="article-top"><span class="eyebrow">THE INVESTIGATION / FOUR CONNECTED QUESTIONS</span><h1>Choose a question.<br>Follow a case.</h1><p class="lede">Each case brings the background, the findings and the unresolved evidence into one reading path. Start with the overview, then follow the supporting chapters.</p></div><div class="case-scope">These are documentary case studies. They do not represent completed person-level legality audits. The remaining 28 jurisdiction files are <a href="../state-files/">reference material in the state directory</a>.</div>'+collection('../',True),'../')
for i,c in enumerate(M['cases']):
 b='../../';g=GROUPS[c['group']]
 body=f'<div class="article-top case-top"><a class="eyebrow" href="../#{g["id"]}">CASE STUDIES / {E(g["title"].upper())}</a><span class="case-place">{E(c["place"])}</span><h1>{E(c["title"])}</h1><p class="lede">{E(c["intro"])}</p></div>'
 body+=f'<section class="case-question"><span class="eyebrow">THE QUESTION</span><h2 id="question">{E(c["question"])}</h2></section>'
 body+='<section class="case-story"><h2 id="story">How the record developed</h2><ol>'+''.join(f'<li><span class="story-step">0{n}</span><div><h3>{E(title)}</h3><p>{E(text)}</p></div></li>' for n,(title,text) in enumerate(c['story'],1))+'</ol></section>'
 body+='<section class="case-findings"><div><span class="eyebrow">WHAT THE RECORD SUPPORTS</span><h2 id="established">What is established</h2><p>'+E(c['established'])+'</p></div><div><span class="eyebrow">THE LIMIT</span><h2 id="limit">Where the evidence stops</h2><p>'+E(c['limit'])+'</p></div></section>'
 body+='<section class="case-missing"><h2 id="unresolved">What remains unresolved</h2><p>'+E(c['missing'])+'</p><p class="small">A documentary finding and an individual outcome are different. We keep the missing evidence visible.</p></section>'
 body+='<section class="case-chapters"><div class="section-head"><div><span class="eyebrow">CONTINUE IN ORDER</span><h2 id="chapters">Read the supporting chapters</h2></div><p>The overview above gives you the story. These chapters let you examine the detail.</p></div><ol>'+''.join(f'<li><a href="{b}{x["path"]}"><span class="chapter-number">{n:02d}</span><div><h3>{E(x["title"])}</h3><p>{E(x["why"])}</p></div><span>→</span></a></li>' for n,x in enumerate(c['sequence'],1))+'</ol></section>'
 body+='<section class="case-source-notes"><h2 id="source-records">The source record</h2><p>Read the review status and qualifications before drawing an outcome conclusion.</p>'+''.join(f'<a href="{b}evidence/#{sid}"><span class="source-id">{sid}</span><strong>{E(SOURCES[sid]["title"])}</strong><span>{E(SOURCES[sid]["type"])}</span></a>' for sid in c['sources'])+'</section>'
 nextcase=M['cases'][(i+1)%len(M['cases'])]
 body+=f'<nav class="case-next" aria-label="Continue exploring"><a href="../#{g["id"]}">← More in {E(g["title"])}</a><a href="../{nextcase["id"]}/">Next case: {E(nextcase["place"])} →</a></nav>'
 write('case-studies/'+c['id'],c['title'],c['question'],body,b)
write('start-here','Start with the question','An introduction to the investigation and its case-led reading paths.', '<div class="article-top"><span class="eyebrow">START HERE</span><h1>First, understand the process.<br>Then follow a case.</h1><p class="lede">SIR stands for Special Intensive Revision: preparing electoral rolls afresh. The investigation asks what the records establish about the process and its effects.</p></div><article class="prose"><h2 id="context">Why the steps matter</h2><p>A draft omission, an application, an accepted claim and a published entry describe different stages. A court ruling also has a defined scope. Read these stages separately before treating them as an outcome for a person.</p><p><a href="../history/">Read the background and chronology</a> · <a href="../national/">Understand the national numbers</a></p><h2 id="choose">Choose the question you care about</h2></article><div class="start-groups">'+''.join(f'<a href="../case-studies/#{g["id"]}"><span class="eyebrow">{E(g["title"])}</span><h3>{E(g["question"])}</h3><p>{E(g["intro"])}</p><span class="more">Explore the cases →</span></a>' for g in M['groups'])+'</div><article class="prose"><h2 id="reading">A consistent reading path</h2><p>Every case starts with the question and the sequence of events. It then separates what is established from what remains unresolved. The supporting chapters follow in order, with the source record alongside them.</p><h2 id="depth">Understand the coverage</h2><p>Eight jurisdictions have developed analysis. Twenty-eight remain reference files. Grouping the material does not turn a reference file into a completed case audit.</p><p><a href="../case-studies/">Choose a case</a> · <a href="../methodology/">Read the editorial method</a></p></article>','../')
# Keep updates inside their case context rather than presenting an unrelated article stream.
write('research','Updates to the case studies','A dated record of how the case studies have developed.', '<div class="article-top"><span class="eyebrow">RESEARCH UPDATES / 17 OCTOBER 2026</span><h1>What changed in the cases.</h1><p class="lede">New records are added to the case they help explain. The overview and reading path keep each update in context.</p></div><div class="update-group"><span class="eyebrow">RETURNING TO THE ROLL / DELHI</span><h2>A court order and a better legal baseline</h2><p>The 14 October court order copy is now inspected. A newer dated ECI Act compilation also improves the legal-source baseline. The wider form challenge and actual inclusion outcomes remain separate questions.</p><a class="button" href="../case-studies/delhi/">Follow the updated Delhi case →</a></div><div class="update-group"><span class="eyebrow">CHECKING THE NUMBERS / UTTARAKHAND</span><h2>All 13 district equations reconciled</h2><p>The final-report check strengthens the aggregate accounting. It does not establish individual eligibility decisions.</p><a class="more" href="../case-studies/uttarakhand/">Follow the district case →</a></div><div class="update-group"><span class="eyebrow">RETURNING TO THE ROLL / MAHARASHTRA</span><h2>Signed extension and application bulletin located</h2><p>The schedule and the intake figures are read together. Gazette publication and matched outcomes remain open.</p><a class="more" href="../case-studies/maharashtra/">Follow the Maharashtra case →</a></div><div class="update-group"><span class="eyebrow">FOLLOWING A CHANGING TIMETABLE / TRIPURA</span><h2>The correction stays in the case</h2><p>The original claims window resolves our earlier error. The later signed replacement timetable is still needed.</p><a class="more" href="../case-studies/tripura/">Read the corrected case →</a></div><div class="insight">The source ledger has 44 records and the claims register has 23 claims. Their existing review qualifications remain in force. <a href="../audit/">See the full research audit.</a></div>','../')
# The directory distinguishes case entry points from research-only reference files.
cards=[]
for j in sorted(D['jurisdictions'],key=lambda x:(x['depth']=='Reference file',x['name'])):
 developed=j['depth']!='Reference file';scope='detailed' if developed else 'reference'
 href='../case-studies/'+j['slug']+'/' if developed else j['slug']+'/'
 label='Case study' if developed else 'Reference file'
 description=next(c['question'] for c in M['cases'] if c['id']==j['slug']) if developed else 'Historical schedule, source references and the local evidence still needed.'
 cards.append(f'<a class="state-card" data-state="{E(j["name"].lower(),quote=True)}" data-scope="{scope}" href="{href}"><span class="count">{label}</span><h3>{E(j["name"])}</h3><p>{E(description)}</p><span class="card-foot">'+('Follow the case' if developed else 'Open reference file')+' <span>→</span></span></a>')
write('state-files','The state directory','Case-study entry points and reference files for all 36 jurisdictions.', '<div class="article-top"><span class="eyebrow">THE STATE DIRECTORY</span><h1>Find the local record.</h1><p class="lede">The eight developed analyses open at their case overview. The remaining 28 files provide reference material and identify the local evidence still missing.</p></div><div class="filterbar"><label>State or Union Territory<input id="state-filter" type="search" placeholder="Search a state…"></label><label>Coverage<select id="state-scope"><option value="detailed">Case study overviews</option><option value="all">All 36 jurisdictions</option><option value="reference">Reference files</option></select></label><span id="state-count" aria-live="polite">36 jurisdictions</span></div><div class="state-grid">'+''.join(cards)+'</div><p class="empty-state hidden" id="state-empty">No matching state. Try another name or choose all jurisdictions.</p>','../')
print('Rendered eight case overviews, grouped hub and introductory guide')
